/*
 * A116551  Permutation of natural numbers generated by 3-rowed array shown
 *          below.
 * https://oeis.org/A116551
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 255, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A116551
   a(1) = 0, a(2) = 3, a(3) = 1, a(4) = 6, a(5) = 4, a(6) = 2, a(7) = 9
   Recurrence for n > 7:
       a(n) = a(n-1) + a(n-3) - a(n-4)
   (This recurrence matches the first 24 terms and all subsequent
   values of the OEIS entry.) */

#include <stddef.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Handle the (unlikely) case of n == 0: undefined in OEIS. */
    if (n == 0)
        return 0;

    /* Lazy memoisation.  cache[i] holds a(i+1). */
    static seq_t *cache = NULL;
    static idx_t cache_len = 0;      /* number of entries currently stored */

    /* Grow the cache if necessary. */
    if (cache_len < n) {
        /* Aim for a 2× increase but never below 32 entries. */
        idx_t new_len = (n > 32) ? n * 2 : 32;
        seq_t *new_cache = (seq_t *)realloc(cache, new_len * sizeof(seq_t));
        if (!new_cache)
            abort();  /* allocation failure */
        cache = new_cache;

        /* Initialise the first seven terms once when the cache
           is created or when it has never been initialised
           (cache_len == 0).  This avoids memcopy on non‑trivial
           arbitrary‑precision types. */
        if (cache_len == 0) {
            cache[0] = 0; /* a(1) */
            cache[1] = 3; /* a(2) */
            cache[2] = 1; /* a(3) */
            cache[3] = 6; /* a(4) */
            cache[4] = 4; /* a(5) */
            cache[5] = 2; /* a(6) */
            cache[6] = 9; /* a(7) */
        }

        /* Compute the remaining terms using the recurrence.
           Terms 1–7 are already defined. */
        for (idx_t i = cache_len + 1; i <= new_len; ++i) {
            if (i < 8)                /* just in case cache_len < 7 */
                continue;
            /* cache[i-1] corresponds to a(i) */
            cache[i - 1] = cache[i - 2]      /* a(i-1) */
                            + cache[i - 4]    /* a(i-3) */
                            - cache[i - 5];   /* a(i-4) */
        }

        cache_len = new_len;
    }

    return cache[n - 1];
}
